from numpy.typing import ndarray

class OptimizedKernel:
    def kernel(self, A: ndarray, b: ndarray, x: ndarray, y: ndarray):
        N = self.N
        # Upper–left triangular elimination
        for i in range(N):
            Ai = A[i]
            for j in range(i):
                w = Ai[j] - Ai[:j].dot(A[:j, j])
                Ai[j] = w / A[j, j]
            for j in range(i, N):
                w = Ai[j] - Ai[:i].dot(A[:i, j])
                Ai[j] = w

        # Forward substitution for y
        w = b[:N].copy()
        for i in range(N):
            w[i] -= A[i, :i].dot(y[:i])
            y[i] = w[i]

        # Backward substitution for x
        for i in range(N - 1, -1, -1):
            wi = y[i] - A[i, i+1:N].dot(x[i+1:N])
            x[i] = wi / A[i, i]

